from pysat.solvers import Glucose3

def solve_langford_sat(n):
    solver = Glucose3()

    # Variables: x[v][i] means number v starts at position i
    # v in 1..n, i in 0..2n-v-2

    var_map = {}
    var_counter = 1
    for v in range(1, n + 1):
        var_map[v] = {}
        for i in range(2 * n - v - 1):
            var_map[v][i] = var_counter
            var_counter += 1

    # 1. Each number v is placed exactly once
    for v in range(1, n + 1):
        vars_v = list(var_map[v].values())
        solver.add_clause(vars_v)
        for i in range(len(vars_v)):
            for j in range(i + 1, len(vars_v)):
                solver.add_clause([-vars_v[i], -vars_v[j]])

    # 2. Each position p is covered exactly once
    for p in range(2 * n):
        covering_vars = []
        for v in range(1, n + 1):
            # Can v start at p?
            if p in var_map[v]:
                covering_vars.append(var_map[v][p])
            # Can v end at p? (meaning it started at p - v - 1)
            if p - v - 1 in var_map[v]:
                covering_vars.append(var_map[v][p - v - 1])

        solver.add_clause(covering_vars)
        for i in range(len(covering_vars)):
            for j in range(i + 1, len(covering_vars)):
                solver.add_clause([-covering_vars[i], -covering_vars[j]])

    if solver.solve():
        model = solver.get_model()
        seq = [0] * (2 * n)
        for v in range(1, n + 1):
            for i in var_map[v]:
                if model[var_map[v][i] - 1] > 0:
                    seq[i] = v
                    seq[i + v + 1] = v
        return seq
    else:
        return None

seq = solve_langford_sat(31)
print(seq)
